<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');
$campaignId=(int)($_GET['campaign_id']??0);$campaigns=pg_query($conn,'SELECT id,title,status FROM feedback_campaigns ORDER BY created_at DESC');$campaign=null;if($campaignId){$r=pg_query_params($conn,'SELECT * FROM feedback_campaigns WHERE id=$1',[$campaignId]);$campaign=$r&&pg_num_rows($r)?pg_fetch_assoc($r):null;}
$totalParticipants=$totalResponses=0;$questions=$submissions=null;if($campaign){$r=pg_query_params($conn,'SELECT COUNT(*) FROM feedback_participants WHERE campaign_id=$1',[$campaignId]);$totalParticipants=(int)pg_fetch_result($r,0,0);$r=pg_query_params($conn,'SELECT COUNT(*) FROM feedback_submissions WHERE campaign_id=$1',[$campaignId]);$totalResponses=(int)pg_fetch_result($r,0,0);$questions=pg_query_params($conn,"SELECT q.*,COUNT(a.id) answer_count,ROUND(AVG(a.rating_value),2) avg_rating FROM feedback_questions q LEFT JOIN feedback_answers a ON a.question_id=q.id WHERE q.campaign_id=$1 GROUP BY q.id ORDER BY q.display_order,q.id",[$campaignId]);$submissions=pg_query_params($conn,'SELECT reference_code,submitted_at FROM feedback_submissions WHERE campaign_id=$1 ORDER BY submitted_at DESC',[$campaignId]);}
admin_page_start('Responses','responses');?>
<div class="hero"><div><h2>Feedback insights</h2><p>Review participation and aggregated answers. Participant identity is kept separate from displayed response content.</p></div></div><div class="card"><form method="get" class="form-grid"><div class="field full"><label>Campaign</label><select name="campaign_id" onchange="this.form.submit()"><option value="">Choose a campaign…</option><?php if($campaigns):while($c=pg_fetch_assoc($campaigns)):?><option value="<?=(int)$c['id']?>" <?=$campaignId===(int)$c['id']?'selected':''?>><?=h($c['title'])?> (<?=h($c['status'])?>)</option><?php endwhile;endif;?></select></div></form></div>
<?php if($campaign):$rate=$totalParticipants?round($totalResponses/$totalParticipants*100,1):0;?><div class="grid stats"><div class="stat"><i class="fa-solid fa-message"></i><strong><?=$totalResponses?></strong><span>Responses</span></div><div class="stat"><i class="fa-solid fa-user-group"></i><strong><?=$totalParticipants?></strong><span>Invited participants</span></div><div class="stat"><i class="fa-solid fa-percent"></i><strong><?=$rate?>%</strong><span>Response rate</span></div><div class="stat"><i class="fa-solid fa-circle-question"></i><strong><?=$questions?pg_num_rows($questions):0?></strong><span>Questions</span></div></div>
<?php if($questions):while($q=pg_fetch_assoc($questions)):?><div class="card"><div style="display:flex;justify-content:space-between;gap:15px"><h3><?=h($q['prompt'])?></h3><span class="badge"><?=h(str_replace('_',' ',$q['question_type']))?></span></div><?php if($q['question_type']==='rating'):?><div class="metric"><?= $q['avg_rating']!==null?h($q['avg_rating']).' / 5':'—' ?></div><div class="help"><?=(int)$q['answer_count']?> rating responses</div><?php elseif(in_array($q['question_type'],['single_choice','multiple_choice'],true)):$options=json_decode($q['options'],true)?:[];foreach($options as $option):$r=pg_query_params($conn,"SELECT COUNT(*) FROM feedback_answers WHERE question_id=$1 AND selected_options ? $2",[(int)$q['id'],$option]);$count=$r?(int)pg_fetch_result($r,0,0):0;$pct=$totalResponses?round($count/$totalResponses*100):0;?><div style="margin:13px 0"><div style="display:flex;justify-content:space-between;font-size:13px"><strong><?=h($option)?></strong><span><?=$count?> · <?=$pct?>%</span></div><div class="progress"><span style="width:<?=$pct?>%"></span></div></div><?php endforeach;else:$r=pg_query_params($conn,"SELECT a.text_value,s.reference_code,s.submitted_at FROM feedback_answers a JOIN feedback_submissions s ON s.id=a.submission_id WHERE a.question_id=$1 AND NULLIF(trim(a.text_value),'') IS NOT NULL ORDER BY s.submitted_at DESC",[(int)$q['id']]);if($r&&pg_num_rows($r)):while($a=pg_fetch_assoc($r)):?><div class="question"><div><?=nl2br(h($a['text_value']))?></div><div class="help"><?=h($a['reference_code'])?> · <?=h(date('M j, Y g:i A',strtotime($a['submitted_at'])))?></div></div><?php endwhile;else:?><div class="empty">No written responses.</div><?php endif;endif;?></div><?php endwhile;endif;?>
<div class="card"><h3>Submission log</h3><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Received</th></tr></thead><tbody><?php if($submissions):while($s=pg_fetch_assoc($submissions)):?><tr><td><span class="badge"><?=h($s['reference_code'])?></span></td><td><?=h(date('M j, Y g:i A',strtotime($s['submitted_at'])))?></td></tr><?php endwhile;endif;if(!$submissions||pg_num_rows($submissions)===0):?><tr><td colspan="2" class="empty">No responses received.</td></tr><?php endif;?></tbody></table></div></div><?php endif;admin_page_end();?>
